theorem kleeneStabIndex_minimal (f : α → α) (hf : Monotone f) {n : ℕ}
    (hn : kleeneChain f n = kleeneChain f (n + 1)) :
    kleeneStabIndex f hf ≤ n

theorem kleeneChain_eq_limit_of_le (f : α → α) (hf : Monotone f) {n : ℕ}
    (hn : kleeneStabIndex f hf ≤ n) :
    kleeneChain f n = kleeneLimit f hf

theorem transportCost_nonneg_of_nonneg {p : α → ℝ} {q : β → ℝ} {c : α → β → ℝ}
    {π : α → β → ℝ} (hπ : IsTransportPlan p q π) (hc : ∀ a b, 0 ≤ c a b) :
    0 ≤ transportCost c π

theorem otValue_le_cost {p : α → ℝ} {q : β → ℝ} {c : α → β → ℝ}
    {π : α → β → ℝ} (hπ : IsTransportPlan p q π) (hc : ∀ a b, 0 ≤ c a b) :
    otValue p q c ≤ transportCost c π
